import{describe,it,expect}from"vitest";import{borderStories,filterBorderStories,findStoryById,findStoryByStates,getUniqueRegions,getUniqueBorderStates}from"../../frontend/border-stories/border-stories.js";const REQUIRED_STORY_FIELDS=["id","states","borderName","region","riverBoundary","dialect","borderFood","borderMarket","tradition","summary","coords"];describe("Border Stories Dataset Integrity",()=>{it("contains at least 15 inter-state border stories in the dataset",()=>{expect(borderStories.length).toBeGreaterThanOrEqual(15)}),it("every border story contains all required fields with non-empty values",()=>{borderStories.forEach((e,t)=>{REQUIRED_STORY_FIELDS.forEach(r=>{expect(e,`Story at index ${t} missing field ${r}`).toHaveProperty(r),"states"===r?(expect(Array.isArray(e.states)).toBe(!0),expect(e.states.length).toBe(2),expect(e.states[0]).not.toBe(e.states[1])):"coords"===r?(expect(typeof e.coords.x).toBe("number"),expect(typeof e.coords.y).toBe("number"),expect(e.coords.x).toBeGreaterThanOrEqual(0),expect(e.coords.x).toBeLessThanOrEqual(900),expect(e.coords.y).toBeGreaterThanOrEqual(0),expect(e.coords.y).toBeLessThanOrEqual(600)):(expect(typeof e[r]).toBe("string"),expect(e[r].trim().length).toBeGreaterThan(0))})})}),it("all story IDs and state pairs are unique",()=>{const e=borderStories.map(e=>e.id),t=new Set(e);expect(t.size).toBe(e.length);const r=new Set(borderStories.map(e=>[...e.states].sort().join("-")));expect(r.size).toBe(borderStories.length)})}),describe("Border Stories Filtering & Search",()=>{it("returns all stories when search query, state, and region are default",()=>{const e=filterBorderStories(borderStories);expect(e.length).toBe(borderStories.length)}),it("filters border stories by search query (e.g. Palakkad or Ganga)",()=>{const e=filterBorderStories(borderStories,{search:"Palakkad"});expect(e.length).toBeGreaterThan(0),e.forEach(e=>{const t=[e.borderName,e.region,e.riverBoundary,e.dialect,e.borderFood,e.borderMarket,e.tradition,e.summary,...e.states].some(e=>e&&e.toLowerCase().includes("palakkad"));expect(t).toBe(!0)})}),it("filters border stories by state code (e.g. WB)",()=>{const e=filterBorderStories(borderStories,{state:"WB"});expect(e.length).toBeGreaterThan(0),e.forEach(e=>{expect(e.states).toContain("WB")})}),it("filters border stories by region (e.g. South)",()=>{const e=filterBorderStories(borderStories,{region:"South"});expect(e.length).toBeGreaterThan(0),e.forEach(e=>{expect(e.region.toLowerCase()).toBe("south")})}),it("handles invalid inputs gracefully",()=>{expect(filterBorderStories(null)).toEqual([]),expect(filterBorderStories([])).toEqual([])})}),describe("Border Stories Traversal & Lookups",()=>{it("finds story by ID correctly",()=>{const e=findStoryById("b-2");expect(e).toBeDefined(),expect(e.borderName).toContain("Palakkad Gap")}),it("finds story by two states in order-independent manner",()=>{const e=findStoryByStates("KL","TN"),t=findStoryByStates("TN","KL");expect(e).toBeDefined(),expect(t).toBeDefined(),expect(e.id).toBe(t.id)}),it("returns undefined when no border story connects given states",()=>{const e=findStoryByStates("JK","TN");expect(e).toBeUndefined()}),it("extracts unique regions sorted alphabetically",()=>{const e=getUniqueRegions(borderStories);expect(e.length).toBeGreaterThan(0);for(let t=1;t<e.length;t++)expect(e[t-1].localeCompare(e[t])).toBeLessThanOrEqual(0)}),it("extracts unique state codes involved in border stories",()=>{const e=getUniqueBorderStates(borderStories);expect(e.length).toBeGreaterThan(0),expect(e).toContain("WB"),expect(e).toContain("TN"),expect(e).toContain("KL"),expect(e).toContain("PB")})});